use \ccxt\Precise;

function precise_equal_position_str($exchange, $result, $key, $expected) {
    return Precise::string_eq($exchange->safe_string($result, $key), $expected);
}


function test_safe_position() {
    $exchange = new \ccxt\async\Exchange(array(
        'id' => 'sampleexchange',
    ));
    // CASE 1 - isolated linear long: derive maintenanceMargin
    // entryMargin = 100, entryPrice = 1000, liquidationPrice = 910, contracts = 2, contractSize = 0.5
    // lossFromEntry = (1000 - 910) * 2 * 0.5 = 90 -> maintenanceMargin = 100 - 90 = 10
    $pos1 = array(
        'marginMode' => 'isolated',
        'side' => 'long',
        'entryPrice' => 1000,
        'liquidationPrice' => 910,
        'contracts' => 2,
        'contractSize' => 0.5,
        'collateral' => 100,
        'initialMargin' => 100,
    );
    $res1 = $exchange->safe_position($pos1);
    assert(precise_equal_position_str($exchange, $res1, 'maintenanceMargin', '10'));
    // CASE 2 - isolated linear short: derive liquidationPrice
    // entryMargin = 100, maintenanceMargin = 10, entryPrice = 1000, contracts = 2, contractSize = 0.5
    // bufferPerUnit = (100 - 10) / (2 * 0.5) = 90 -> liquidationPrice = 1000 + 90 = 1090
    $pos2 = array(
        'marginMode' => 'isolated',
        'side' => 'short',
        'entryPrice' => 1000,
        'contracts' => 2,
        'contractSize' => 0.5,
        'collateral' => 100,
        'initialMargin' => 100,
        'maintenanceMargin' => 10,
    );
    $res2 = $exchange->safe_position($pos2);
    assert(precise_equal_position_str($exchange, $res2, 'liquidationPrice', '1090'));
    // CASE 3 - isolated linear long: derive entryPrice
    $pos3 = array(
        'marginMode' => 'isolated',
        'side' => 'long',
        'liquidationPrice' => 910,
        'contracts' => 2,
        'contractSize' => 0.5,
        'collateral' => 100,
        'initialMargin' => 100,
        'maintenanceMargin' => 10,
    );
    $res3 = $exchange->safe_position($pos3);
    assert(precise_equal_position_str($exchange, $res3, 'entryPrice', '1000'));
    // CASE 4 - isolated linear long: derive contracts
    $pos4 = array(
        'marginMode' => 'isolated',
        'side' => 'long',
        'entryPrice' => 1000,
        'liquidationPrice' => 910,
        'contractSize' => 0.5,
        'collateral' => 100,
        'initialMargin' => 100,
        'maintenanceMargin' => 10,
    );
    $res4 = $exchange->safe_position($pos4);
    assert(precise_equal_position_str($exchange, $res4, 'contracts', '2'));
    // CASE 5 - isolated linear long: derive contractSize
    $pos5 = array(
        'marginMode' => 'isolated',
        'side' => 'long',
        'entryPrice' => 1000,
        'liquidationPrice' => 910,
        'contracts' => 2,
        'collateral' => 100,
        'initialMargin' => 100,
        'maintenanceMargin' => 10,
    );
    $res5 = $exchange->safe_position($pos5);
    assert(precise_equal_position_str($exchange, $res5, 'contractSize', '0.5'));
    // CASE 6 - isolated linear long: derive collateral and initialMargin
    $pos6 = array(
        'marginMode' => 'isolated',
        'side' => 'long',
        'entryPrice' => 1000,
        'liquidationPrice' => 910,
        'contracts' => 2,
        'contractSize' => 0.5,
        'maintenanceMargin' => 10,
    );
    $res6 = $exchange->safe_position($pos6);
    assert(precise_equal_position_str($exchange, $res6, 'initialMargin', '100'));
    assert(precise_equal_position_str($exchange, $res6, 'collateral', '100'));
    // CASE 7 - isolated linear with unrealizedPnl included in collateral
    // collateral = 115, unrealizedPnl = 15 -> entryMargin = 100 -> maintenanceMargin = 10
    $pos7 = array(
        'marginMode' => 'isolated',
        'side' => 'long',
        'entryPrice' => 1000,
        'liquidationPrice' => 910,
        'contracts' => 2,
        'contractSize' => 0.5,
        'collateral' => 115,
        'unrealizedPnl' => 15,
    );
    $res7 = $exchange->safe_position($pos7);
    assert(precise_equal_position_str($exchange, $res7, 'maintenanceMargin', '10'));
    // CASE 8 - cross margin position must not derive isolated maintenanceMargin
    $pos8 = array(
        'marginMode' => 'cross',
        'side' => 'long',
        'entryPrice' => 1000,
        'liquidationPrice' => 910,
        'contracts' => 2,
        'contractSize' => 0.5,
        'collateral' => 100,
        'initialMargin' => 100,
    );
    $res8 = $exchange->safe_position($pos8);
    assert($exchange->safe_value($res8, 'maintenanceMargin') === null);
    // CASE 9 - cross margin linear position derives notional, unrealizedPnl, initialMarginPercentage, initialMargin, maintenanceMargin, marginRatio, percentage
    $pos9 = array(
        'marginMode' => 'cross',
        'side' => 'long',
        'entryPrice' => 1000,
        'markPrice' => 1050,
        'contracts' => 2,
        'contractSize' => 0.5,
        'leverage' => 10,
        'maintenanceMarginPercentage' => 0.01,
        'collateral' => 210,
    );
    $res9 = $exchange->safe_position($pos9);
    assert(precise_equal_position_str($exchange, $res9, 'notional', '1050'));
    assert(precise_equal_position_str($exchange, $res9, 'unrealizedPnl', '50'));
    assert(precise_equal_position_str($exchange, $res9, 'initialMarginPercentage', '0.1'));
    assert(precise_equal_position_str($exchange, $res9, 'initialMargin', '105'));
    assert(precise_equal_position_str($exchange, $res9, 'maintenanceMargin', '10.5'));
    assert(precise_equal_position_str($exchange, $res9, 'marginRatio', '0.05'));
    assert(precise_equal_position_str($exchange, $res9, 'percentage', '47.61'));
    // CASE 10 - cross margin position derives leverage, maintenanceMarginPercentage, and markPrice
    $pos10 = array(
        'marginMode' => 'cross',
        'side' => 'short',
        'notional' => 2000,
        'contracts' => 4,
        'contractSize' => 0.5,
        'initialMarginPercentage' => 0.05,
        'maintenanceMargin' => 20,
    );
    $res10 = $exchange->safe_position($pos10);
    assert(precise_equal_position_str($exchange, $res10, 'markPrice', '1000'));
    assert(precise_equal_position_str($exchange, $res10, 'leverage', '20'));
    assert(precise_equal_position_str($exchange, $res10, 'initialMargin', '100'));
    assert(precise_equal_position_str($exchange, $res10, 'maintenanceMarginPercentage', '0.01'));
    // CASE 11 - negative collateral position must not derive initialMargin or maintenanceMargin
    $pos11 = array(
        'marginMode' => 'isolated',
        'side' => 'long',
        'entryPrice' => 74.35,
        'liquidationPrice' => 60.07,
        'markPrice' => 74.43,
        'notional' => 7.443,
        'leverage' => 5,
        'contracts' => 1,
        'contractSize' => 0.1,
        'collateral' => -3.967,
        'unrealizedPnl' => 0.008,
    );
    $res11 = $exchange->safe_position($pos11);
    assert($exchange->safe_value($res11, 'initialMargin') === null);
    assert($exchange->safe_value($res11, 'maintenanceMargin') === null);
    assert($exchange->safe_value($res11, 'positionMargin') === null);
    // CASE 12 - margin given: collateral = margin + unrealizedPnl, and margin drives the liquidation equation
    $pos12 = array(
        'marginMode' => 'isolated',
        'side' => 'long',
        'entryPrice' => 100,
        'liquidationPrice' => 90.5,
        'contracts' => 1,
        'contractSize' => 1,
        'positionMargin' => 10,
        'unrealizedPnl' => 2,
    );
    $res12 = $exchange->safe_position($pos12);
    assert(precise_equal_position_str($exchange, $res12, 'collateral', '12'));
    assert(precise_equal_position_str($exchange, $res12, 'maintenanceMargin', '0.5'));
    // CASE 13 - isolated collateral given without margin: margin = collateral - unrealizedPnl
    $pos13 = array(
        'marginMode' => 'isolated',
        'side' => 'short',
        'entryPrice' => 100,
        'contracts' => 2,
        'contractSize' => 1,
        'initialMargin' => 20,
        'collateral' => 17,
        'unrealizedPnl' => -3,
    );
    $res13 = $exchange->safe_position($pos13);
    assert(precise_equal_position_str($exchange, $res13, 'positionMargin', '20'));
}
